describe('Video Captions Accessibility', () => {
    beforeEach(() => {
        cy.visit('/video-page'); // Replace with the actual URL of the video page
    });

    it('should display captions when the video is played', () => {
        cy.get('video').should('exist').then(($video) => {
            $video[0].play();
            cy.get('.caption').should('be.visible');
        });
    });

    it('should not display captions when captions are turned off', () => {
        cy.get('.caption-toggle').click(); // Assuming there's a toggle for captions
        cy.get('video').should('exist').then(($video) => {
            $video[0].play();
            cy.get('.caption').should('not.be.visible');
        });
    });
});
